// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set the jojoTeam address to this test contract
        address jojoTeam = address(this);
        // Call as the JOJO team member (which is the deployer, so msg.sender == address(this))
        // In the reference, require(msg.sender == jojoTeam) passes; in the bug, require(msg.sender != jojoTeam) fails
        bool ok = false;
        try c.newEmergencyOracle("test description") {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference returns true (no revert), the bug returns false (revert)
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set jojoTeam to address(this) by default (from deployment)
        // Use a non-owner caller
        address nonOwner = address(0x123);
        vm.prank(nonOwner);
        bool ok = true;
        try c.newEmergencyOracle("test") {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: non-owner is not jojoTeam, so require(msg.sender == jojoTeam) fails and call reverts -> ok = false
        // Bug: require(msg.sender != jojoTeam) passes for non-owner, call succeeds -> ok = true
        assertTrue(!ok);
    }
}
